import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const r = new Readable({ read() {} });
  const held: any = r.toArray();
  const r2: any = new Readable({ read() {} });
  setTimeout(() => { r.push('a'); r.push(null); r2.push('x'); r2.push('y'); r2.push(null); }, 5);
  for await (const c of r2) console.log(String(c));
  console.log(String((await held)[0]));
}
